"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["4589"],{30134(e){e.exports=JSON.parse('{"tag":{"label":"features","permalink":"/fr/tags/features","allTagsPath":"/fr/tags","count":10,"items":[{"id":"features/calendar-and-appointments","title":"Calendrier et rendez-vous","description":"Un calendrier pour la semaine ordinaire comme pour la semaine m\xe9dicale, avec une liste de questions sur chaque rendez-vous.","permalink":"/fr/features/calendar-and-appointments"},{"id":"features/maps","title":"Cartes et lieux","description":"Suivez les liens entre souvenirs, notes, proches, \xe9v\xe9nements et noms de lieux enregistr\xe9s. L\u2019historique de position est une option distincte.","permalink":"/fr/features/maps"},{"id":"features/community-and-chats","title":"Communaut\xe9 et conversations","description":"Groupes avec publications et r\xe9ponses, messages entre comptes connect\xe9s, blocage et mod\xe9ration sans r\xe9v\xe9ler \xe0 l\u2019auteur l\u2019identit\xe9 de la personne qui l\u2019a signal\xe9.","permalink":"/fr/features/community-and-chats"},{"id":"features/blood-donation","title":"Don de sang","description":"Un annuaire public de donneurs, des demandes cibl\xe9es et une communication des coordonn\xe9es \xe0 une seule personne, une seule fois, que le donneur peut retirer.","permalink":"/fr/features/blood-donation"},{"id":"features/shopping-list","title":"La liste de courses","description":"Une liste issue de vos repas et recettes ou \xe9crite \xe0 la main, partageable en texte brut sans imposer de compte \xe0 la personne qui fait les courses.","permalink":"/fr/features/shopping-list"},{"id":"features/referrals","title":"Le programme de parrainage","description":"Invitez quelqu\u2019un. Une inscription confirm\xe9e donne des points, un badge et, au-del\xe0 d\u2019un seuil, un mois d\u2019offre payante. Tous les chiffres sont r\xe9glables par l\u2019administration.","permalink":"/fr/features/referrals"},{"id":"features/tools","title":"Outils et calculateurs","description":"Les calculateurs pr\xe9sents dans LifeWell, ceux h\xe9berg\xe9s sur ZTools et la raison pour laquelle le r\xe9pertoire des outils contient surtout des liens.","permalink":"/fr/features/tools"},{"id":"features/professionals","title":"Professionnels","description":"Un annuaire de professionnels inscrits eux-m\xeames. LifeWell ne v\xe9rifie pas leurs qualifications\u202F; il affiche leur num\xe9ro d\u2019inscription et un lien vers le registre pour que vous puissiez le consulter.","permalink":"/fr/features/professionals"},{"id":"features/reminders","title":"Rappels","description":"Ce que LifeWell peut vous rappeler, quand et sur quel appareil\u202F: trois interrupteurs g\xe9n\xe9raux, des heures calmes et aucune autorisation d\u2019alarme exacte sur Android.","permalink":"/fr/features/reminders"},{"id":"features/search","title":"Recherche","description":"Une seule recherche dans tout votre dossier. La partie serveur existe, mais la page n\u2019est pas termin\xe9e\u202F; l\u2019application le dit au lieu d\u2019afficher une liste vide.","permalink":"/fr/features/search"}],"unlisted":false}}')}}]);